export function LivePayments({flash}:{flash:Flash}){const payments=useCollection('payments'),invoices=useCollection('invoices'),clients=useCollection('clients');const [dialog,setDialog]=useState(false);const save=(v:Values)=>{const inv=invoices.find(i=>i.id===v.invoiceId);if(!inv){flash('Choose an invoice for this payment.');return}const amount=Number(v.amount),balance=Math.max(0,invoiceTotal(inv)-sum(payments.filter(p=>p.invoiceId===inv.id),p=>p.amount));if(amount<=0||amount>balance){flash(`Enter a payment above zero and no greater than the ${money(balance)} balance.`);return}createRecord('payments',{invoiceId:inv.id,clientId:inv.clientId,amount,date:String(v.date),method:String(v.method??'Bank transfer'),note:String(v.note??'')});const totalReceived=sum(payments.filter(p=>p.invoiceId===inv.id),p=>p.amount)+amount;if(totalReceived>=invoiceTotal(inv))updateRecord('invoices',inv.id,{status:'Paid'});else if(inv.status==='Draft')updateRecord('invoices',inv.id,{status:'Pending'});setDialog(false);flash(`Payment of ${money(amount)} recorded.`);};return <div className="page"><Header eyebrow="MONEY IN MOTION" title="Payments" desc="A clearer look at what’s come in and what’s on its way." action={<Action onClick={()=>setDialog(true)}>＋ Add payment</Action>}/><div className="metrics-grid compact"><Stat label="Received" value={money(sum(payments,p=>p.amount))} sub={`${payments.length} transactions`}/><Stat label="Awaiting payment" value={money(sum(invoices.filter(i=>i.status==='Pending'),invoiceTotal))} sub={`${invoices.filter(i=>i.status==='Pending').length} invoices`} tone="amber"/><Stat label="Overdue" value={money(sum(invoices.filter(i=>i.status==='Overdue'),invoiceTotal))} sub={`${invoices.filter(i=>i.status==='Overdue').length} invoices`} tone="red"/><Stat label="Transactions" value={String(payments.length)} sub="All recorded payments" tone="blue"/></div><section className="panel payments-panel"><div className="panel-head"><div><h2>Transactions</h2><p>Payments received and matched to invoices.</p></div></div><div className="data-table-wrap"><table><thead><tr><th>INVOICE</th><th>CLIENT</th><th>DATE</th><th>METHOD</th><th>AMOUNT</th><th>NOTE</th></tr></thead><tbody>{payments.map(p=><tr key={p.id}><td>{invoices.find(i=>i.id===p.invoiceId)?.number??'Unlinked'}</td><td>{clientName(p.clientId,clients)}</td><td>{dateText(p.date)}</td><td>{p.method}</td><td className="strong-cell">{money(p.amount)}</td><td>{p.note}</td></tr>)}</tbody></table>{!payments.length&&<p className="empty-copy padded">No payments recorded yet. Add a payment against an invoice.</p>}</div></section>{dialog&&<Dialog kind="payment" onClose={()=>setDialog(false)} onSave={save}/>}</div>}

